changeSet.sql:
COMMENT ON TABLE ylab_schema.users IS 'Таблица пользователей';
COMMENT ON COLUMN ylab_schema.users.id IS 'Идентификатор пользователя';
COMMENT ON COLUMN ylab_schema.users.email IS 'Email адрес пользователя';
COMMENT ON COLUMN ylab_schema.users.name IS 'Имя пользователя';
COMMENT ON COLUMN ylab_schema.users.password IS 'Пароль пользователя';
COMMENT ON COLUMN ylab_schema.users.role IS 'Роль пользователя (USER или ADMIN)';
COMMENT ON COLUMN ylab_schema.users.is_blocked IS 'Статус блокировки пользователя';

COMMENT ON TABLE ylab_schema.habits IS 'Таблица привычек';
COMMENT ON COLUMN ylab_schema.habits.id IS 'Идентификатор привычки';
COMMENT ON COLUMN ylab_schema.habits.title IS 'Название привычки';
COMMENT ON COLUMN ylab_schema.habits.description IS 'Описание привычки';
COMMENT ON COLUMN ylab_schema.habits.frequency IS 'Частота выполнения привычки';

COMMENT ON TABLE ylab_schema.records IS 'Таблица записей о привычках';
COMMENT ON COLUMN ylab_schema.records.id IS 'Идентификатор записи';
COMMENT ON COLUMN ylab_schema.records.date IS 'Дата выполнения привычки';
COMMENT ON COLUMN ylab_schema.records.completed IS 'Статус выполнения привычки';
